import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    managers = []
    for i in range(1, n + 1):
        managers.append(int(input_data[i]))

    depth = [0] * (n + 1)

    def get_depth(emp):
        if depth[emp] != 0:
            return depth[emp]

        manager = managers[emp - 1]
        if manager == -1:
            depth[emp] = 1
        else:
            depth[emp] = get_depth(manager) + 1

        return depth[emp]

    max_depth = 0
    for i in range(1, n + 1):
            d = get_depth(i)
            if d > max_depth:
                max_depth = d

    print(max_depth)

if __name__ == "__main__":
    main()
